"use client";

import { useState } from "react";
import { Paperclip, X } from "lucide-react";
import { cn } from "@/lib/utils";
import { panel } from "@/lib/takt-surface";
import { PromptBox } from "./prompt-box";
import { LessonCitation } from "./lesson-citation";

type Citation = Pick<
  React.ComponentProps<typeof LessonCitation>,
  "title" | "locator" | "excerpt" | "href"
>;
export type TutorAnswer = { text: string; citation?: Citation };
const defaultContext = ["lesson.md § 2.3", "pattern.regex"];
const suggestions = ["Почему тест упал?", "Как работает повторение?"];
export function AskTutor({
  context = defaultContext,
  onAsk,
  onReturn,
  className,
}: {
  context?: string[];
  onAsk?: (question: string, context: string[]) => Promise<TutorAnswer>;
  onReturn?: () => void;
  className?: string;
}) {
  const [removed, setRemoved] = useState<string[]>([]);
  const [answer, setAnswer] = useState<TutorAnswer | null>(null);
  const attached = context.filter((value) => !removed.includes(value));
  async function ask(question: string) {
    setAnswer(null);
    const result = onAsk
      ? await onAsk(question, attached)
      : {
          text:
            attached.length && question !== suggestions[1]
              ? "Сравните UI-7 и UI-42. Сколько цифр допускает часть [0-9] вашего шаблона?"
              : "Попробуйте сравнить шаблоны [0-9] и [0-9]+ на строке из двух цифр.",
          citation: {},
        };
    setAnswer(result);
  }
  return (
    <section className={cn(panel, "grid w-80 max-w-full gap-3", className)}>
      <div className="flex justify-between gap-2">
        <strong>Спросить по уроку</strong>
        {!onAsk && <small className="text-muted-foreground">Демоответ</small>}
      </div>
      <div className="flex flex-wrap gap-1">
        {attached.map((source) => (
          <button
            key={source}
            type="button"
            onClick={() => setRemoved((prev) => [...prev, source])}
            aria-label={"Убрать источник " + source}
            className="inline-flex max-w-full min-h-7 items-center gap-1 rounded-md border px-1.5 font-mono text-[10px]"
          >
            <Paperclip size={11} />
            <span className="min-w-0 truncate">{source}</span>
            <X size={11} />
          </button>
        ))}
      </div>
      <PromptBox
        className="w-full p-2 shadow-none"
        suggestions={suggestions}
        onSend={ask}
      />
      <div aria-live="polite" className="empty:hidden">
        {answer && (
          <div
            key={answer.text}
            className="grid gap-2 border-t pt-2 text-sm motion-safe:animate-in motion-safe:fade-in"
          >
            <p>{answer.text}</p>
            {answer.citation && (
              <LessonCitation
                {...answer.citation}
                className="w-full"
                onReturn={onReturn}
              />
            )}
          </div>
        )}
      </div>
    </section>
  );
}

"use client";
import { cn } from "@/lib/utils";
import { useRef, useState } from "react";
import { ArrowUp, Check, LoaderCircle, Undo2 } from "lucide-react";
import { panel } from "@/lib/takt-surface";
export function PromptBox({
  className,
  onSend,
  suggestions = ["Найти идею", "Уточнить задачу"],
}: {
  className?: string;
  suggestions?: string[];
  onSend?: (text: string) => void | Promise<void>;
}) {
  const [text, setText] = useState("");
  const [last, setLast] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(false);
  const field = useRef<HTMLTextAreaElement>(null);
  const pending = useRef(false);
  async function send() {
    const message = text.trim();
    if (!message || pending.current) return;
    pending.current = true;
    setBusy(true);
    setError(false);
    try {
      await onSend?.(message);
      setLast(message);
      setText("");
    } catch {
      setError(true);
    } finally {
      pending.current = false;
      setBusy(false);
    }
  }
  return (
    <form
      className={cn(panel + " grid w-72 max-w-full gap-2", className)}
      onSubmit={(e) => {
        e.preventDefault();
        void send();
      }}
    >
      {last && (
        <div className="flex items-center gap-1.5 rounded-lg bg-muted px-2 py-1.5 text-xs motion-safe:animate-in motion-safe:slide-in-from-bottom-1">
          <Check size={13} />
          <output className="min-w-0 flex-1 truncate">{last}</output>
          <button
            type="button"
            aria-label="Редактировать прошлый запрос"
            disabled={busy}
            onClick={() => {
              setText(last);
              setLast("");
              field.current?.focus();
            }}
          >
            <Undo2 size={14} />
          </button>
        </div>
      )}
      {!text && !last && suggestions.length > 0 && (
        <div className="flex flex-wrap gap-1">
          {suggestions.map((v) => (
            <button
              type="button"
              className="rounded-md border bg-muted px-2.5 py-1.5 text-[11px] hover:bg-background"
              key={v}
              onClick={() => {
                setText(v);
                field.current?.focus();
              }}
            >
              {v}
            </button>
          ))}
        </div>
      )}
      <textarea
        ref={field}
        rows={2}
        aria-label="Запрос"
        readOnly={busy}
        placeholder="О чём спросить?"
        value={text}
        onChange={(e) => {
          setText(e.target.value);
          setError(false);
        }}
        onKeyDown={(e) => {
          if (e.nativeEvent.isComposing || e.keyCode === 229) return;
          if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent.isComposing) {
            e.preventDefault();
            void send();
          }
        }}
        className="min-w-0 resize-none rounded-md bg-transparent px-1 text-sm leading-relaxed outline-offset-2"
      />
      <div className="flex items-center justify-between border-t pt-2">
        <small role="status" className="text-[10px] text-muted-foreground">
          {error ? "Не удалось отправить" : "Shift + Enter · новая строка"}
        </small>
        <button
          type="submit"
          aria-label="Отправить"
          disabled={busy || !text.trim()}
          className="grid size-8 place-items-center rounded-full bg-primary text-primary-foreground motion-safe:transition-transform motion-safe:active:scale-90 disabled:opacity-35"
        >
          {busy ? (
            <LoaderCircle className="motion-safe:animate-spin" size={15} />
          ) : (
            <ArrowUp size={16} />
          )}
        </button>
      </div>
    </form>
  );
}

"use client";

import { useId, useRef, useState } from "react";
import { BookOpen, CornerUpLeft } from "lucide-react";
import { cn } from "@/lib/utils";

export function LessonCitation({
  title = "Повторения в шаблоне",
  locator = "§ 2.3",
  excerpt = "Квантификатор + повторяет предыдущий элемент один или несколько раз. Например, [a-z]+ совпадает с целым словом из строчных латинских букв.",
  href,
  onReturn,
  className,
}: {
  title?: string;
  locator?: string;
  excerpt?: string;
  href?: string;
  onReturn?: () => void;
  className?: string;
}) {
  const [open, setOpen] = useState(false);
  const id = useId();
  const button = useRef<HTMLButtonElement>(null);
  return (
    <div className={cn("w-64 max-w-full text-sm", className)}>
      <button
        ref={button}
        type="button"
        aria-expanded={open}
        aria-controls={id}
        onClick={() => setOpen(!open)}
        className="inline-flex max-w-full items-center gap-2 rounded-lg border bg-card px-3 py-2 text-start font-medium text-card-foreground shadow-sm"
      >
        <BookOpen size={15} className="shrink-0 text-primary" />
        <span>{title}</span>
        <small className="whitespace-nowrap font-mono text-muted-foreground">
          {locator}
        </small>
      </button>
      <div
        id={id}
        hidden={!open}
        className="mt-2 rounded-xl border bg-card p-3 text-card-foreground motion-safe:animate-in motion-safe:slide-in-from-top-1"
      >
        <blockquote className="text-sm leading-relaxed">{excerpt}</blockquote>
        <div className="mt-3 flex flex-wrap items-center gap-3 text-xs">
          {href && (
            <a className="underline underline-offset-2" href={href}>
              Открыть урок
            </a>
          )}
          <button
            type="button"
            className="inline-flex items-center gap-1 font-medium text-primary"
            onClick={() => {
              setOpen(false);
              button.current?.focus({ preventScroll: true });
              onReturn?.();
            }}
          >
            <CornerUpLeft size={13} />
            Вернуться
          </button>
        </div>
      </div>
    </div>
  );
}

// Semantic shadcn colors keep the surfaces usable in a host project's own theme.
export const panel =
  "rounded-2xl border border-foreground/10 bg-card p-4 text-sm text-card-foreground shadow-[0_2px_5px_#0000000a,0_8px_18px_-12px_#0003]";
export const field =
  "min-h-10 min-w-0 w-full rounded-xl border border-foreground/10 bg-muted/70 px-3 text-sm text-foreground outline-none motion-safe:transition-[background-color,box-shadow] focus:bg-background focus:ring-1 focus:ring-foreground/35";
export const action =
  "inline-flex min-h-10 cursor-pointer items-center justify-center gap-2 rounded-xl border border-foreground/10 bg-primary px-3.5 py-2 text-sm font-semibold text-primary-foreground shadow-sm outline-offset-4 motion-safe:transition-[transform,box-shadow] motion-safe:active:translate-y-px motion-safe:active:scale-[.97] disabled:cursor-default disabled:opacity-50";
export const secondary =
  "inline-flex min-h-9 cursor-pointer items-center justify-center gap-1.5 rounded-lg border border-foreground/10 bg-background px-3 text-xs font-medium text-foreground outline-offset-2 hover:bg-muted motion-safe:transition-[transform,background-color] motion-safe:active:scale-[.96] disabled:cursor-default disabled:opacity-45";
